import Image from "next/image";

export default function Hero() {
  return (
    <section
      id="start"
      className="overflow-hidden border-b border-[#DED5C7] bg-[#F7F2E9] pt-20"
    >
      <div className="mx-auto grid max-w-7xl items-center gap-10 px-6 py-10 lg:min-h-[570px] lg:grid-cols-[0.9fr_1.1fr] lg:px-8">
        <div className="mx-auto max-w-xl text-center lg:mx-0 lg:text-left">
          <Image
            src="/images/brand/fio-logo.png"
            alt="Figuring It Out"
            width={132}
            height={132}
            priority
            className="mx-auto h-auto w-[110px] object-contain lg:mx-0 lg:w-[125px]"
          />

          <p className="mt-4 text-[11px] uppercase tracking-[0.42em] text-[#234531]">
            Figuring It Out™
          </p>

          <h1 className="mt-4 font-serif text-5xl leading-[0.98] text-[#5A2346] sm:text-6xl lg:text-[4.4rem]">
            Choosing to keep moving
            <span className="mt-2 block text-[#234531]">
              when life doesn&apos;t make sense.
            </span>
          </h1>

          <div className="mx-auto my-5 flex items-center justify-center gap-3 lg:mx-0 lg:justify-start">
            <span className="h-px w-14 bg-[#C89D4A]" />
            <span className="h-2 w-2 rotate-45 bg-[#C89D4A]" />
            <span className="h-px w-14 bg-[#C89D4A]" />
          </div>

          <p className="max-w-lg text-[15px] leading-7 text-[#373832]">
            Figuring It Out™ is the lifelong practice of moving through
            uncertainty, trusting that understanding—and eventually
            confidence—will grow with every step.
          </p>

          <p className="mt-4 font-serif text-lg italic text-[#5A2346]">
            There isn&apos;t one right path.
          </p>

          <p className="mt-1 font-serif text-xl italic text-[#B77A24]">
            Only the one that&apos;s right for you.
          </p>

          <a
            href="#choose-your-path"
            className="mt-7 inline-flex items-center gap-3 rounded-sm bg-[#234531] px-6 py-3 text-xs uppercase tracking-[0.16em] text-white transition hover:bg-[#5A2346]"
          >
            Begin Your Journey
            <span aria-hidden="true">↓</span>
          </a>
        </div>

        <div className="relative min-h-[390px] overflow-hidden rounded-t-[9rem] rounded-b-md border border-[#D5C5AE] shadow-[0_24px_60px_rgba(67,50,39,0.17)] sm:min-h-[470px] lg:min-h-[510px]">
          <Image
            src="/images/jenn-and-girls.jpg"
            alt="Jenn laughing with her daughters"
            fill
            priority
            sizes="(min-width: 1024px) 55vw, 100vw"
            className="object-cover object-[center_38%]"
          />

          <div className="absolute inset-0 bg-gradient-to-t from-[#1D2D23]/25 via-transparent to-transparent" />

          <Image
            src="/images/brand/fio-logo.png"
            alt=""
            width={210}
            height={210}
            aria-hidden="true"
            className="absolute bottom-5 right-6 w-[115px] opacity-[0.1] brightness-0 invert"
          />
        </div>
      </div>
    </section>
  );
}